 23	/** The HTTP API the inn's website and front desk call. */
 24	public final class HttpApi {
 25	
 26	    private final Javalin server;
 27	    private final Rooms rooms;
 28	    private final ReservationService reservations;
 29	    private final SentMessages sentMessages;
 30	    private final OccupancyReport occupancyReport;
 31	    private final RevenueReport revenueReport;
 32	
 33	    public HttpApi(
 34	            Rooms rooms,
 35	            ReservationService reservations,
 36	            SentMessages sentMessages,
 37	            OccupancyReport occupancyReport,
 38	            RevenueReport revenueReport) {
 39	        this.rooms = rooms;
 40	        this.reservations = reservations;
 41	        this.sentMessages = sentMessages;
 42	        this.occupancyReport = occupancyReport;
 43	        this.revenueReport = revenueReport;
 44	
 45	        ObjectMapper jsonMapper = JsonMapper.builder()
 46	                .addModule(new JavaTimeModule())
 47	                .disable(SerializationFeature.WRITE_DATES_AS_TIMESTAMPS)
 48	                .build();
 49	        this.server = Javalin.create(config -> {
 50	            config.showJavalinBanner = false;
 51	            config.jsonMapper(new JavalinJackson(jsonMapper, false));
 52	        });
 53	        registerRoutes();
 54	        registerErrorHandling();
 55	    }
 56	
 57	    public Javalin server() {
 58	        return server;
 59	    }
 60	
 61	    private void registerRoutes() {
 62	        server.get("/rooms", ctx -> ctx.json(rooms.all()));
 63	
 64	        server.post("/reservations", ctx -> {
 65	            NewReservation request = readNewReservation(ctx);
 66	            ctx.status(201).json(new ReservationResponse(reservations.create(request)));
 67	        });
 68	        server.get("/reservations/{id}", ctx ->
 69	                ctx.json(new ReservationResponse(reservations.find(reservationId(ctx)))));
 70	        server.post("/reservations/{id}/confirmation", ctx ->
 71	                ctx.json(new ReservationResponse(reservations.confirm(reservationId(ctx)))));
 72	        server.post("/reservations/{id}/cancellation", ctx ->
 73	                ctx.json(new ReservationResponse(reservations.cancel(reservationId(ctx)))));
 74	        server.post("/reservations/{id}/check-in", ctx ->
 75	                ctx.json(new ReservationResponse(reservations.checkIn(reservationId(ctx)))));
 76	        server.post("/reservations/{id}/check-out", ctx ->
 77	                ctx.json(reservations.checkOut(reservationId(ctx))));
 78	        server.get("/reservations/{id}/document", ctx ->
 79	                ctx.json(reservations.receiptCopy(reservationId(ctx))));
 80	
 81	        server.get("/messages", ctx -> ctx.json(sentMessages.all()));
 82	
 83	        server.get("/reports/occupancy", ctx -> {
 84	            LocalDate night = readDate(ctx);
 85	            ctx.contentType("text/csv; charset=utf-8").result(occupancyReport.generate(night));
 86	        });
 87	        server.get("/reports/revenue", ctx -> {
 88	            YearMonth month = readMonth(ctx);
 89	            ctx.contentType("text/csv; charset=utf-8").result(revenueReport.generate(month));
 90	        });
 91	    }
 92	
 93	    private void registerErrorHandling() {
 94	        server.exception(HotelException.class, (exception, ctx) -> {
 95	            ctx.status(httpStatus(exception.errorCode()));
 96	            ctx.json(new ErrorResponse(exception.errorCode().name(), exception.getMessage()));
 97	        });
 98	    }
 99	
100	    private static int httpStatus(ErrorCode errorCode) {
101	        return switch (errorCode) {
102	            case INVALID_REQUEST -> 400;
103	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
104	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
105	            case CAPACITY_EXCEEDED -> 422;
106	        };
107	    }
108	
109	    private static NewReservation readNewReservation(Context ctx) {
110	        CreateReservationRequest body;
111	        try {
112	            body = ctx.bodyAsClass(CreateReservationRequest.class);
113	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
114	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
115	        }
116	        if (body == null
117	                || body.roomNumber() == null
118	                || isBlank(body.guestName())
119	                || isBlank(body.guestEmail())
120	                || isBlank(body.guestCpf())
121	                || body.checkIn() == null
122	                || body.checkOut() == null
123	                || body.guests() == null
124	                || body.ratePlan() == null) {
125	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
126	        }
127	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
128	        return new NewReservation(
129	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan());
130	    }
131	
132	    private static long reservationId(Context ctx) {
133	        String id = ctx.pathParam("id");
134	        try {
135	            return Long.parseLong(id);
136	        } catch (NumberFormatException notANumber) {
137	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
138	        }
139	    }
140	
141	    private static LocalDate readDate(Context ctx) {
142	        String date = requiredQueryParam(ctx, "date");
143	        try {
144	            return LocalDate.parse(date);
145	        } catch (DateTimeParseException badDate) {
146	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + date + "' is not a date (yyyy-MM-dd)");
147	        }
148	    }
149	
150	    private static YearMonth readMonth(Context ctx) {
151	        String month = requiredQueryParam(ctx, "month");
152	        try {
153	            return YearMonth.parse(month);
154	        } catch (DateTimeParseException badMonth) {
155	            throw new HotelException(ErrorCode.INVALID_REQUEST, "'" + month + "' is not a month (yyyy-MM)");
156	        }
157	    }
158	
159	    private static String requiredQueryParam(Context ctx, String name) {
160	        String value = ctx.queryParam(name);
161	        if (value == null) {
162	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the query parameter '" + name + "' is required");
163	        }
164	        return value;
165	    }
166	
167	    private static boolean isBlank(String text) {
168	        return text == null || text.isBlank();
169	    }
170	}
171	package hotel.reservations;
172	
173	import hotel.documents.ReservationReceipt;
174	import hotel.messages.EmailSender;
175	import hotel.rooms.Room;
176	import hotel.rooms.Rooms;
177	import java.math.BigDecimal;
178	
179	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
180	public final class ReservationService {
181	
182	    static final String HOTEL_NAME = "Pousada Maré Alta";
183	
184	    private final Rooms rooms;
185	    private final ReservationStore store;
186	    private final PriceCalculator priceCalculator;
187	    private final EmailSender emailSender;
188	
189	    public ReservationService(
190	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
191	        this.rooms = rooms;
192	        this.store = store;
193	        this.priceCalculator = priceCalculator;
194	        this.emailSender = emailSender;
195	    }
196	
197	    public synchronized Reservation create(NewReservation request) {
198	        if (!request.checkOut().isAfter(request.checkIn())) {
199	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
200	        }
201	        if (request.guests() < 1) {
202	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
203	        }
204	        Room room = rooms.find(request.roomNumber())
205	                .orElseThrow(() -> new HotelException(
206	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
207	        if (request.guests() > room.capacity()) {
208	            throw new HotelException(
209	                    ErrorCode.CAPACITY_EXCEEDED,
210	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
211	        }
212	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
213	            throw new HotelException(
214	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
215	        }
216	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request.ratePlan());
217	        return store.add(request, price);
218	    }
219	
220	    public Reservation find(long reservationId) {
221	        return store.find(reservationId)
222	                .orElseThrow(() -> new HotelException(
223	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
224	    }
225	
226	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
227	    public synchronized Reservation confirm(long reservationId) {
228	        Reservation reservation = find(reservationId);
229	        if (reservation.status() != ReservationStatus.PENDING) {
230	            throw notAllowed(reservation, "confirm");
231	        }
232	        reservation.confirmPayment();
233	        store.update(reservation);
234	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
235	        emailSender.send(
236	                reservation.guest().email(),
237	                "Reserva confirmada - " + HOTEL_NAME,
238	                confirmationEmailBody(reservation, receipt));
239	        return reservation;
240	    }
241	
242	    /**
243	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
244	     * reservation was never paid, so nothing comes back).
245	     */
246	    public synchronized Reservation cancel(long reservationId) {
247	        Reservation reservation = find(reservationId);
248	        if (reservation.status() != ReservationStatus.PENDING
249	                && reservation.status() != ReservationStatus.CONFIRMED) {
250	            throw notAllowed(reservation, "cancel");
251	        }
252	        BigDecimal refund = switch (reservation.ratePlan()) {
253	            case STANDARD -> reservation.amountPaid();
254	            case NON_REFUNDABLE -> PriceCalculator.cents(BigDecimal.ZERO);
255	        };
256	        reservation.cancel(refund);
257	        store.update(reservation);
258	        return reservation;
259	    }
260	
261	    public synchronized Reservation checkIn(long reservationId) {
262	        Reservation reservation = find(reservationId);
263	        if (reservation.status() != ReservationStatus.CONFIRMED) {
264	            throw notAllowed(reservation, "check in");
265	        }
266	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
267	        store.update(reservation);
268	        return reservation;
269	    }
270	
271	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
272	    public synchronized ReservationReceipt checkOut(long reservationId) {
273	        Reservation reservation = find(reservationId);
274	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
275	            throw notAllowed(reservation, "check out");
276	        }
277	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
278	        store.update(reservation);
279	        return new ReservationReceipt(reservation, roomOf(reservation));
280	    }
281	
282	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
283	    public ReservationReceipt receiptCopy(long reservationId) {
284	        Reservation reservation = find(reservationId);
285	        if (!reservation.isPaid()) {
286	            throw notAllowed(reservation, "issue a receipt for");
287	        }
288	        return new ReservationReceipt(reservation, roomOf(reservation));
289	    }
290	
291	    private Room roomOf(Reservation reservation) {
292	        return rooms.find(reservation.roomNumber()).orElseThrow();
293	    }
294	
295	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
296	        return "Olá, " + reservation.guest().name() + "!\n\n"
297	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
298	                + receipt.text() + "\n"
299	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
300	                + "Até breve!\n";
301	    }
302	
303	    private static HotelException notAllowed(Reservation reservation, String operation) {
304	        return new HotelException(
305	                ErrorCode.OPERATION_NOT_ALLOWED,
306	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
307	    }
308	}

